dtsPropsFor.AgentPip:
/** Lifecycle state. Drives colour and mark: pulsing dot (running), hollow ring (pending/idle), filled dot (terminal). */
  state: 'running' | 'background' | 'completed' | 'failed' | 'stopped' | 'waiting' | 'needs-you' | 'paused' | 'result-ready' | 'reviewed' | 'attention' | 'resumable' | 'stale' | 'resumed';
  /** 6px (xs) for dense count strips, 8px (sm) for rows. Default 'sm'. */
  size?: 'xs' | 'sm';

dtsPropsFor.AgentHandle:
/** The worker's display name, already stripped of any leading @ (e.g. "Ada", "Turing"). */
  name: string;
  /** Optional extra classes on the name span. */
  className?: string;

dtsPropsFor.AgentStateLabel:
/** Lifecycle state. Renders as a pip plus its full word, e.g. a purple "Waiting on the assistant". */
  state: 'running' | 'background' | 'completed' | 'failed' | 'stopped' | 'waiting' | 'needs-you' | 'paused' | 'result-ready' | 'reviewed' | 'attention' | 'resumable' | 'stale' | 'resumed';
  /** Pip size. Default 'sm'. */
  size?: 'xs' | 'sm';

dtsPropsFor.AgentSectionLabel:
/** Caption text. Rendered uppercase with wide tracking. */
  children: React.ReactNode;
  /** Caption colour. Default 'muted'. */
  tone?: 'muted' | 'accent' | 'lease' | 'warn';

dtsPropsFor.AgentActionButton:
/** Button text. */
  label: string;
  /** Outline tone. 'danger' is the shipped case (worker Stop). Default 'neutral'. */
  tone?: 'neutral' | 'accent' | 'danger';
  /** Native title attribute. */
  title?: string;
  onClick: () => void;
